with gaps as (select *, case when lag(txn_time) over (partition by txn_type order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by txn_type order by txn_time, id) + interval '60' day then 1 else 0 end as is_new_burst from transactions), sessionized as (select id, account_id, txn_type, txn_time, merchant, is_flagged, sum(is_new_burst) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as island_id from gaps) select case when island_id >= 8 then 'PREMIUM' else 'STANDARD' end as island_id_tier, min(txn_time) as started_at, sum(case when merchant = '7-Eleven' then island_id else 0 end) as 7_eleven_island_id, sum(case when txn_type = 'FEE' then island_id else 0 end) as fee_island_id from sessionized group by 1 having sum(case when txn_type = 'FEE' then island_id else 0 end) > 0
